struct Params { time: f32 }
@group(0) @binding(0) var<uniform> params: Params;

struct VSOut {
  @builtin(position) pos: vec4f,
  @location(0) uv: vec2f,
}

@vertex fn vs_main(@builtin(vertex_index) i: u32) -> VSOut {
  var p = array<vec2f, 3>(vec2f(-1.0, -1.0), vec2f(3.0, -1.0), vec2f(-1.0, 3.0));
  var o: VSOut;
  o.pos = vec4f(p[i], 0.0, 1.0);
  o.uv = vec2f(p[i].x * 0.5 + 0.5, 1.0 - (p[i].y * 0.5 + 0.5));
  return o;
}

fn hash21(p: vec2f) -> f32 {
  return fract(sin(dot(p, vec2f(127.1, 311.7))) * 43758.5453123);
}

fn noise(p: vec2f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = hash21(i);
  let b = hash21(i + vec2f(1.0, 0.0));
  let c = hash21(i + vec2f(0.0, 1.0));
  let d = hash21(i + vec2f(1.0, 1.0));
  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn fbm(p: vec2f) -> f32 {
  var v = 0.0;
  var a = 0.5;
  var q = p;
  for (var k = 0; k < 5; k = k + 1) {
    v = v + a * noise(q);
    q = q * 2.07 + vec2f(11.3, 5.7);
    a = a * 0.5;
  }
  return v;
}

fn curl(p: vec2f, e: f32) -> vec2f {
  let nL = fbm(p - vec2f(e, 0.0));
  let nR = fbm(p + vec2f(e, 0.0));
  let nD = fbm(p - vec2f(0.0, e));
  let nU = fbm(p + vec2f(0.0, e));
  return vec2f(nU - nD, nL - nR) / (2.0 * e);
}

fn palette(h: f32) -> vec3f {
  let x = fract(h);
  let c0 = vec3f(1.00, 0.10, 0.58);
  let c1 = vec3f(1.00, 0.74, 0.08);
  let c2 = vec3f(1.00, 0.28, 0.16);
  let c3 = vec3f(0.06, 0.94, 0.78);
  let c4 = vec3f(0.78, 0.16, 1.00);
  if (x < 0.25) { return mix(c0, c1, x / 0.25); }
  if (x < 0.50) { return mix(c1, c2, (x - 0.25) / 0.25); }
  if (x < 0.75) { return mix(c2, c3, (x - 0.50) / 0.25); }
  return mix(c3, c4, (x - 0.75) / 0.25);
}

fn rot(p: vec2f, a: f32) -> vec2f {
  let c = cos(a);
  let s = sin(a);
  return vec2f(c * p.x - s * p.y, s * p.x + c * p.y);
}

@fragment fn fs_main(@location(0) uv: vec2f) -> @location(0) vec4f {
  let t = params.time;
  var p = (uv - vec2f(0.5, 0.5)) * vec2f(0.5625, 1.0) * 2.20;
  p = rot(p, t * 0.17);

  let pot = p * 1.28 + vec2f(t * 0.38, -t * 0.27);
  var flow = curl(pot, 0.020);
  p = p + normalize(flow + vec2f(0.0001, 0.0)) * 0.18 * tanh(length(flow) * 0.08);

  let pot2 = p * 2.55 + vec2f(-t * 0.46, t * 0.21) + flow * 0.12;
  let flow2 = curl(pot2, 0.014);
  p = p + flow2 * 0.055;

  let ang = t * 0.73;
  let c = vec2f(-0.54 + 0.24 * cos(ang), 0.52 + 0.20 * sin(ang * 0.71 + 0.35));

  var z = p;
  var trapA = 4.0;
  var trapC = 4.0;
  var trapP = 4.0;
  var trapR = 4.0;
  var lastZ = p;

  for (var i = 0; i < 16; i = i + 1) {
    z = vec2f(z.x * z.x - z.y * z.y, 2.0 * z.x * z.y) + c;
    let r = length(z);
    trapA = min(trapA, min(abs(z.x), abs(z.y)));
    trapC = min(trapC, abs(r - 0.62));
    trapP = min(trapP, length(z - vec2f(0.38 * sin(t * 0.61), 0.28 * cos(t * 0.43))));
    trapR = min(trapR, r);
    lastZ = z;
    if (r > 12.0) { break; }
  }

  let filA = exp(-trapA * 16.0);
  let filC = exp(-trapC * 13.0);
  let filP = exp(-trapP * 20.0);
  let filaments = max(filA, max(filC * 0.88, filP * 0.72));

  let ribbon = abs(sin(fbm(p * 2.35 + vec2f(t * 0.19, -t * 0.11)) * 6.28318 + t * 0.92));
  let filR = pow(1.0 - ribbon, 10.0);

  let hue = trapA * 2.2 + trapC * 1.5 + t * 0.14 + length(p) * 0.16 + atan2(lastZ.y, lastZ.x) * 0.08;
  var col = palette(hue);
  col = mix(col, palette(hue + 0.34), filC);
  col = mix(col, vec3f(1.0, 0.86, 0.32), filP * 0.58);
  col = mix(col, palette(hue + 0.58 + t * 0.05), filR * 0.45);

  let field = exp(-trapR * 0.48) * 0.28;
  col = col * (0.22 + 0.92 * filaments + 0.55 * filR);
  col = col + palette(hue + 0.5) * field;
  col = col + vec3f(1.0, 0.52, 0.82) * pow(filaments, 2.2) * 0.70;
  col = col + vec3f(1.0, 0.90, 0.40) * pow(filA, 3.0) * 0.50;
  col = col + vec3f(1.0, 0.45, 0.22) * pow(filR, 2.6) * 0.28;

  let bg = vec3f(0.07, 0.018, 0.038);
  let cover = clamp(0.18 + filaments * 1.35 + field * 1.7 + filR * 0.55, 0.0, 1.0);
  col = mix(bg, col, cover);

  let vig = smoothstep(1.22, 0.26, length((uv - vec2f(0.5, 0.5)) * vec2f(1.14, 1.0)));
  col = col * (0.64 + 0.36 * vig);
  col = pow(clamp(col, vec3f(0.0), vec3f(1.40)), vec3f(0.86));
  return vec4f(col, 1.0);
}
